package care.tend.habit;
import care.tend.common.CurrentUser;import care.tend.item.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.time.temporal.TemporalAdjusters;import java.util.*;
@RestController@RequestMapping("/api/habits")public class HabitController{private final LifeItemRepository items;private final HabitLogRepository logs;public HabitController(LifeItemRepository items,HabitLogRepository logs){this.items=items;this.logs=logs;}
 public record LogRequest(String state,@PositiveOrZero BigDecimal actualValue,@Size(max=1000)String note){}public record Metrics(long successfulDays,long partialDays,long recordedDays,long scheduledDays,double completionRate,int currentStreak,int longestStreak){}public record CalendarResponse(YearMonth month,List<LifeItem>habits,List<HabitLog>logs,Map<UUID,Metrics>analytics){}
 @GetMapping("/calendar")CalendarResponse calendar(@RequestParam YearMonth month){var uid=CurrentUser.id();var habits=items.findAllByUserIdAndTypeOrderByCreatedAtDesc(uid,LifeItem.Type.HABIT).stream().filter(h->!"ARCHIVED".equals(h.status)).toList();var monthLogs=logs.findAllByUserIdAndCompletionDateBetweenOrderByCompletionDate(uid,month.atDay(1),month.atEndOfMonth());var byHabit=new HashMap<UUID,List<HabitLog>>();monthLogs.forEach(l->byHabit.computeIfAbsent(l.habitId,k->new ArrayList<>()).add(l));var metrics=new LinkedHashMap<UUID,Metrics>();habits.forEach(h->metrics.put(h.id,metrics(h,byHabit.getOrDefault(h.id,List.of()),month)));return new CalendarResponse(month,habits,monthLogs,metrics);}
 @PutMapping("/{habitId}/logs/{date}")@Transactional HabitLog upsert(@PathVariable UUID habitId,@PathVariable LocalDate date,@Valid@RequestBody LogRequest r){var uid=CurrentUser.id();var habit=items.findByIdAndUserId(habitId,uid).filter(i->i.type==LifeItem.Type.HABIT).orElseThrow();var log=logs.findByUserIdAndHabitIdAndCompletionDate(uid,habitId,date).orElseGet(HabitLog::new);log.userId=uid;log.habitId=habitId;log.completionDate=date;log.actualValue=r.actualValue();log.note=r.note();log.state=r.state()==null?HabitRules.deriveState(habit,r.actualValue()):r.state();if(!Set.of("COMPLETED","PARTIAL","SKIPPED","MISSED").contains(log.state))throw new IllegalArgumentException("Unsupported habit status");return logs.save(log);}
 @DeleteMapping("/{habitId}/logs/{date}")@ResponseStatus(HttpStatus.NO_CONTENT)void clear(@PathVariable UUID habitId,@PathVariable LocalDate date){var uid=CurrentUser.id();items.findByIdAndUserId(habitId,uid).filter(i->i.type==LifeItem.Type.HABIT).orElseThrow();logs.findByUserIdAndHabitIdAndCompletionDate(uid,habitId,date).ifPresent(logs::delete);}
 private Metrics metrics(LifeItem h,List<HabitLog>ls,YearMonth m){var today=LocalDate.now();var end=m.atEndOfMonth().isAfter(today)?today:m.atEndOfMonth();int scheduled=0,streak=0,longest=0;var states=new HashMap<LocalDate,String>();ls.forEach(l->states.put(l.completionDate,l.state));for(var d=m.atDay(1);!d.isAfter(end);d=d.plusDays(1)){if(!HabitRules.isScheduled(h,d))continue;scheduled++;var s=states.get(d);if("COMPLETED".equals(s)||"PARTIAL".equals(s)){streak++;longest=Math.max(longest,streak);}else if(s!=null&&!"SKIPPED".equals(s))streak=0;}long success=ls.stream().filter(l->"COMPLETED".equals(l.state)||"PARTIAL".equals(l.state)).count();long partial=ls.stream().filter(l->"PARTIAL".equals(l.state)).count();long recorded=ls.size();double rate=scheduled==0?0:Math.round(success*1000.0/scheduled)/10.0;return new Metrics(success,partial,recorded,scheduled,rate,streak,longest);}}
